var HORIZON_TESTNET = "https://horizon-testnet.stellar.org";
var MERCHANT_ADDRESS = "GBBATDYWQWD4EPQNQQSTUABAF3COF2RZAOY6NHVOI5JU4PU4DDBPS673";
var PRICE_USD = 4.97;
var PRODUCT = "India eSIM, 1 GB / 7 days";
var PAY_AMOUNT = null;
StellarWalletsKit.init({
  network: Networks.TESTNET,
  modules: [new FreighterModule(), new xBullModule()]
});
var els = {
  connectBtn: document.getElementById("connect-btn"),
  address: document.getElementById("address"),
  payBtn: document.getElementById("pay-btn"),
  status: document.getElementById("status"),
  result: document.getElementById("result"),
  quote: document.getElementById("quote")
};
async function loadQuote() {
  try {
    const r7 = await fetch("https://api.coingecko.com/api/v3/simple/price?ids=stellar&vs_currencies=usd");
    const rate = (await r7.json()).stellar.usd;
    PAY_AMOUNT = (PRICE_USD / rate).toFixed(7);
    els.quote.textContent = `$${PRICE_USD} = ${Number(PAY_AMOUNT).toFixed(2)} XLM at ${rate} USD/XLM`;
  } catch {
    PAY_AMOUNT = "25";
    els.quote.textContent = "Rate unavailable: using 25 testnet XLM";
  }
}
loadQuote();
var buyerAddress = null;
function setStatus(text) {
  els.status.textContent = text;
}
function randomMemo() {
  return "GX" + Math.floor(1e8 + Math.random() * 9e8).toString();
}
els.connectBtn.addEventListener("click", async () => {
  setStatus("Opening wallet selector...");
  try {
    const { address } = await StellarWalletsKit.authModal();
    const { networkPassphrase } = await StellarWalletsKit.getNetwork();
    if (networkPassphrase !== Networks2.TESTNET) {
      buyerAddress = null;
      els.payBtn.disabled = true;
      setStatus("Your wallet is on the wrong network.");
      els.result.innerHTML = '<p class="error">Switch your wallet to Testnet (in Freighter: Settings, Network, Testnet), then connect again.</p>';
      return;
    }
    buyerAddress = address;
    els.address.textContent = address;
    els.payBtn.disabled = false;
    setStatus("Wallet connected. Ready to pay on testnet.");
  } catch (err) {
    setStatus("Stopped.");
    els.result.innerHTML = `<p class="error">${err.message || err}</p>`;
  }
});
els.payBtn.addEventListener("click", async () => {
  if (!buyerAddress || !PAY_AMOUNT) return;
  els.payBtn.disabled = true;
  els.result.textContent = "";
  const memo = randomMemo();
  try {
    setStatus("Loading your testnet account...");
    const accountResp = await fetch(
      `${HORIZON_TESTNET}/accounts/${buyerAddress}`
    );
    if (!accountResp.ok) {
      throw new Error(
        "This wallet has no funded testnet account yet. Fund it at https://friendbot.stellar.org/?addr=" + buyerAddress
      );
    }
    const accountData = await accountResp.json();
    const account = new Account(buyerAddress, accountData.sequence);
    setStatus(
      `Building a ${Number(PAY_AMOUNT).toFixed(2)} XLM payment to Genghis with memo ${memo}...`
    );
    const tx3 = new TransactionBuilder(account, {
      fee: BASE_FEE,
      networkPassphrase: Networks2.TESTNET
    }).addOperation(
      Operation2.payment({
        destination: MERCHANT_ADDRESS,
        asset: Asset.native(),
        amount: PAY_AMOUNT
      })
    ).addMemo(Memo.text(memo)).setTimeout(120).build();
    setStatus("Waiting for your wallet to sign...");
    const { signedTxXdr } = await StellarWalletsKit.signTransaction(
      tx3.toXDR(),
      { address: buyerAddress, networkPassphrase: Networks2.TESTNET }
    );
    setStatus("Submitting the signed payment to Stellar testnet...");
    const submitResp = await fetch(`${HORIZON_TESTNET}/transactions`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: "tx=" + encodeURIComponent(signedTxXdr)
    });
    const submitData = await submitResp.json();
    if (!submitResp.ok || submitData.status === "ERROR") {
      throw new Error(
        "Stellar rejected the transaction: " + JSON.stringify(submitData.extras?.result_codes || submitData)
      );
    }
    setStatus("Payment settled. Confirming the memo landed on Genghis...");
    const confirmResp = await fetch(
      `${HORIZON_TESTNET}/transactions/${submitData.hash}`
    );
    const confirmData = await confirmResp.json();
    if (confirmData.memo !== memo) {
      throw new Error("Memo mismatch: the deposit cannot be attributed.");
    }
    const code = "GENGHIS-TESTNET-" + memo.slice(2);
    setStatus("Delivered.");
    els.result.innerHTML = `
      <p><strong>Payment confirmed on Stellar testnet.</strong></p>
      <p>${PRODUCT}. Your eSIM code: <code>${code}</code></p>
      <p>Transaction: <a href="https://stellar.expert/explorer/testnet/tx/${submitData.hash}" target="_blank" rel="noopener">${submitData.hash}</a></p>
      <p>This is the synchronous path the grant brings to Genghis on mainnet, for people and, through the x402 memo bridge, for agents (see ARCHITECTURE.md, flows A and B).</p>
    `;
  } catch (err) {
    setStatus("Stopped.");
    els.result.innerHTML = `<p class="error">${err.message || err}</p>`;
  } finally {
    els.payBtn.disabled = false;
  }
});
